import { createServer } from 'node:http';
import { WebSocket, WebSocketServer } from 'ws';

const rooms = new Map();
const server = createServer();
const wss = new WebSocketServer({ noServer: true, maxPayload: 64 * 1024 });
server.on('upgrade', (request, socket, head) => {
  const url = new URL(request.url, 'http://localhost');
  const room = url.searchParams.get('room');
  if (url.pathname !== '/ws' || !room || !/^[a-z0-9-]{1,32}$/.test(room)) {
    socket.destroy(); return;
  }
  const origin = request.headers.origin;
  if (origin && origin !== 'http://localhost:4400') { socket.destroy(); return; }
  wss.handleUpgrade(request, socket, head, (peer) => {
    if (!rooms.has(room)) rooms.set(room, new Set());
    const members = rooms.get(room);
    members.add(peer);
    peer.on('error', console.error);
    peer.on('close', () => {
      members.delete(peer);
      if (members.size === 0) rooms.delete(room);
    });
    peer.on('message', (data, isBinary) => {
      for (const other of members) {
        if (other.readyState !== WebSocket.OPEN) continue;
        if (other.bufferedAmount > 1_000_000) { other.close(1009, 'slow client'); continue; }
        other.send(data, { binary: isBinary });
      }
    });
  });
});
server.listen(8080, () => console.log('Rooms: ws://localhost:8080/ws?room=updates'));

