package main

import (
  "log"
  "net/http"
  "regexp"
  "sync"
  "time"
  "github.com/gorilla/websocket"
)

type peer struct { conn *websocket.Conn; write sync.Mutex }
var rooms = map[string]map[*peer]struct{}{}
var roomsMu sync.Mutex
var roomName = regexp.MustCompile(`^[a-z0-9-]{1,32}$`)
var upgrader = websocket.Upgrader{CheckOrigin: func(r *http.Request) bool {
  origin := r.Header.Get("Origin")
  return origin == "" || origin == "http://localhost:4400"
}}

func main() {
  http.HandleFunc("/ws", func(w http.ResponseWriter, r *http.Request) {
    room := r.URL.Query().Get("room")
    if !roomName.MatchString(room) { http.Error(w, "invalid room", 400); return }
    conn, err := upgrader.Upgrade(w, r, nil)
    if err != nil { return }
    p := &peer{conn: conn}
    roomsMu.Lock()
    if rooms[room] == nil { rooms[room] = map[*peer]struct{}{} }
    rooms[room][p] = struct{}{}
    roomsMu.Unlock()
    defer func() {
      roomsMu.Lock()
      delete(rooms[room], p)
      if len(rooms[room]) == 0 { delete(rooms, room) }
      roomsMu.Unlock()
      conn.Close()
    }()
    conn.SetReadLimit(64 << 10)
    for {
      kind, message, err := conn.ReadMessage()
      if err != nil { return }
      roomsMu.Lock()
      members := make([]*peer, 0, len(rooms[room]))
      for other := range rooms[room] { members = append(members, other) }
      roomsMu.Unlock()
      for _, other := range members {
        other.write.Lock()
        other.conn.SetWriteDeadline(time.Now().Add(5 * time.Second))
        err := other.conn.WriteMessage(kind, message)
        other.write.Unlock()
        if err != nil { other.conn.Close() }
      }
    }
  })
  log.Println("Rooms: ws://localhost:8080/ws?room=updates")
  log.Fatal(http.ListenAndServe(":8080", nil))
}

