using System.Collections.Concurrent;
using System.Net.WebSockets;
using System.Text.RegularExpressions;

var builder = WebApplication.CreateBuilder(args);
builder.WebHost.UseUrls("http://localhost:8080");
var app = builder.Build();
var options = new WebSocketOptions();
options.AllowedOrigins.Add("http://localhost:4400");
app.UseWebSockets(options);
var rooms = new ConcurrentDictionary<string, ConcurrentDictionary<Guid, Peer>>();
app.Map("/ws", async context =>
{
    var room = context.Request.Query["room"].ToString();
    if (!Regex.IsMatch(room, "^[a-z0-9-]{1,32}$") || !context.WebSockets.IsWebSocketRequest)
    {
        context.Response.StatusCode = 400;
        return;
    }
    using var socket = await context.WebSockets.AcceptWebSocketAsync();
    var group = rooms.GetOrAdd(room, _ => new ConcurrentDictionary<Guid, Peer>());
    var id = Guid.NewGuid();
    group[id] = new Peer(socket);
    var buffer = new byte[4096];
    try
    {
        while (socket.State == WebSocketState.Open)
        {
            using var message = new MemoryStream();
            WebSocketReceiveResult result;
            do
            {
                result = await socket.ReceiveAsync(new ArraySegment<byte>(buffer), context.RequestAborted);
                if (result.MessageType == WebSocketMessageType.Close)
                {
                    await socket.CloseAsync(WebSocketCloseStatus.NormalClosure, "bye", CancellationToken.None);
                    return;
                }
                if (message.Length + result.Count > 64 * 1024)
                {
                    await socket.CloseAsync(WebSocketCloseStatus.MessageTooBig, "message too large", CancellationToken.None);
                    return;
                }
                message.Write(buffer, 0, result.Count);
            } while (!result.EndOfMessage);

            var payload = message.ToArray();
            foreach (var other in group.Values)
            {
                await other.SendGate.WaitAsync(context.RequestAborted);
                try
                {
                    if (other.Socket.State == WebSocketState.Open)
                        await other.Socket.SendAsync(new ArraySegment<byte>(payload),
                            result.MessageType, true, context.RequestAborted);
                }
                catch (WebSocketException) { /* Peer disconnected during send. */ }
                finally { other.SendGate.Release(); }
            }
        }
    }
    finally { group.TryRemove(id, out _); }
});
app.Run();

