import { WebSocket, WebSocketServer } from 'ws';

const wss = new WebSocketServer({ port: 8080, path: '/ws', maxPayload: 64 * 1024 });
const alive = new WeakMap();
wss.on('connection', (socket) => {
  alive.set(socket, true);
  socket.on('error', console.error);
  socket.on('pong', () => alive.set(socket, true));
  socket.on('message', (data, isBinary) => socket.send(data, { binary: isBinary }));
});
const timer = setInterval(() => {
  for (const socket of wss.clients) {
    if (!alive.get(socket)) { socket.terminate(); continue; }
    alive.set(socket, false);
    if (socket.readyState === WebSocket.OPEN) socket.ping();
  }
}, 30_000);
wss.on('close', () => clearInterval(timer));
console.log('Heartbeat: ws://localhost:8080/ws');

let socket, retryTimer;
let stopped = false;
let delay = 1000;
function connect() {
  socket = new WebSocket('ws://localhost:8080/ws');
  socket.onopen = () => { delay = 1000; socket.send('hello'); };
  socket.onmessage = (event) => console.log(event.data);
  socket.onclose = () => {
    if (!stopped) {
      retryTimer = setTimeout(connect, delay);
      delay = Math.min(delay * 2, 30000);
    }
  };
}
function stop() { stopped = true; clearTimeout(retryTimer); socket?.close(); }
connect();

