package main

import (
  "log"
  "net/http"
  "time"
  "github.com/gorilla/websocket"
)

var upgrader = websocket.Upgrader{CheckOrigin: func(r *http.Request) bool {
  origin := r.Header.Get("Origin")
  return origin == "" || origin == "http://localhost:4400"
}}

func main() {
  http.HandleFunc("/ws", func(w http.ResponseWriter, r *http.Request) {
    conn, err := upgrader.Upgrade(w, r, nil)
    if err != nil { return }
    defer conn.Close()
    conn.SetReadLimit(64 << 10)
    conn.SetReadDeadline(time.Now().Add(45 * time.Second))
    conn.SetPongHandler(func(string) error {
      return conn.SetReadDeadline(time.Now().Add(45 * time.Second))
    })
    done := make(chan struct{})
    ticker := time.NewTicker(30 * time.Second)
    defer ticker.Stop()
    defer close(done)
    go func() {
      for {
        select {
        case <-done: return
        case <-ticker.C:
          if err := conn.WriteControl(websocket.PingMessage, nil,
            time.Now().Add(5 * time.Second)); err != nil { conn.Close(); return }
        }
      }
    }()
    for {
      kind, data, err := conn.ReadMessage() // Reads process pong frames too.
      if err != nil { return }
      if err := conn.WriteMessage(kind, data); err != nil { return }
    }
  })
  log.Println("Heartbeat: ws://localhost:8080/ws")
  log.Fatal(http.ListenAndServe(":8080", nil))
}

